"""Freshness of a stored HTTP response, an RFC 9111 subset. See task.md."""

from __future__ import annotations

import calendar
import re
from dataclasses import dataclass
from datetime import datetime, timezone

FRESH = "FRESH"
STALE = "STALE"
MUST_REVALIDATE = "MUST_REVALIDATE"

_DAYS = ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
_MONTHS = ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")
_DATE_RE = re.compile(
    r"^(?P<day>" + "|".join(_DAYS) + r"), (?P<dom>\d{2}) (?P<mon>" + "|".join(_MONTHS) + r")"
    r" (?P<year>\d{4}) (?P<hh>\d{2}):(?P<mm>\d{2}):(?P<ss>\d{2}) GMT$"
)
_DIGITS_RE = re.compile(r"[0-9]+")


class HeaderError(ValueError):
    """Raised for a header that is not a well-formed HTTP-date."""


@dataclass(frozen=True)
class Result:
    verdict: str
    current_age: int
    freshness_lifetime: int


def _get_header(headers: dict[str, str], name: str) -> str | None:
    name_lower = name.lower()
    for key, value in headers.items():
        if key.lower() == name_lower:
            return value
    return None


def _parse_http_date(raw: str) -> int:
    s = raw.strip()
    match = _DATE_RE.match(s)
    if match is None:
        raise HeaderError(f"not a well-formed HTTP-date: {raw!r}")
    dom = int(match.group("dom"))
    month = _MONTHS.index(match.group("mon")) + 1
    year = int(match.group("year"))
    hh = int(match.group("hh"))
    mm = int(match.group("mm"))
    ss = int(match.group("ss"))
    try:
        dt = datetime(year, month, dom, hh, mm, ss, tzinfo=timezone.utc)
    except ValueError as exc:
        raise HeaderError(f"not a real date/time: {raw!r}") from exc
    return calendar.timegm(dt.utctimetuple())


def _split_directives(s: str) -> list[str]:
    parts = []
    current = []
    in_quotes = False
    for ch in s:
        if ch == '"':
            in_quotes = not in_quotes
            current.append(ch)
        elif ch == "," and not in_quotes:
            parts.append("".join(current))
            current = []
        else:
            current.append(ch)
    parts.append("".join(current))
    return parts


def _parse_cache_control(raw: str) -> dict[str, str | None]:
    directives: dict[str, str | None] = {}
    for part in _split_directives(raw):
        token = part.strip()
        if not token:
            continue
        name, sep, value = token.partition("=")
        name = name.strip().lower()
        if not name:
            continue
        if not sep:
            directives[name] = None
            continue
        value = value.strip()
        if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
            value = value[1:-1]
        directives[name] = value
    return directives


def _numeric_directive(directives: dict[str, str | None], name: str) -> int | None:
    if name not in directives:
        return None
    value = directives[name]
    if value is None:
        return None
    if _DIGITS_RE.fullmatch(value):
        return int(value)
    return None


def evaluate(
    response_headers: dict[str, str],
    request_headers: dict[str, str],
    request_time: int,
    response_time: int,
    now: int,
) -> Result:
    """Decide whether the stored response may be reused at `now`."""
    response_cc = _parse_cache_control(_get_header(response_headers, "Cache-Control") or "")
    request_cc = _parse_cache_control(_get_header(request_headers, "Cache-Control") or "")

    date_header = _get_header(response_headers, "Date")
    date = _parse_http_date(date_header) if date_header is not None else response_time

    expires_header = _get_header(response_headers, "Expires")
    expires = _parse_http_date(expires_header) if expires_header is not None else None

    last_modified_header = _get_header(response_headers, "Last-Modified")
    last_modified = (
        _parse_http_date(last_modified_header) if last_modified_header is not None else None
    )

    age_header = _get_header(response_headers, "Age")
    age = int(age_header) if age_header is not None and _DIGITS_RE.fullmatch(age_header) else 0

    response_delay = response_time - request_time
    apparent_age = max(0, response_time - date)
    corrected_age = age + response_delay
    initial_age = max(apparent_age, corrected_age)
    resident_time = now - response_time
    current_age = initial_age + resident_time

    s_maxage = _numeric_directive(response_cc, "s-maxage")
    max_age = _numeric_directive(response_cc, "max-age")
    if s_maxage is not None:
        lifetime = s_maxage
    elif max_age is not None:
        lifetime = max_age
    elif expires is not None:
        lifetime = expires - date
    elif last_modified is not None:
        lifetime = (date - last_modified) // 10
    else:
        lifetime = 0
    lifetime = max(0, lifetime)

    req_max_age = _numeric_directive(request_cc, "max-age")
    if req_max_age is not None:
        lifetime = min(lifetime, req_max_age)

    must_revalidate = (
        "no-store" in response_cc
        or "no-cache" in response_cc
        or "must-revalidate" in response_cc
        or "no-cache" in request_cc
    )

    if must_revalidate:
        verdict = MUST_REVALIDATE
    else:
        min_fresh = _numeric_directive(request_cc, "min-fresh") or 0
        if lifetime > current_age + min_fresh:
            verdict = FRESH
        elif "max-stale" in request_cc:
            if request_cc["max-stale"] is None:
                verdict = FRESH
            else:
                max_stale_n = _numeric_directive(request_cc, "max-stale")
                if max_stale_n is not None and current_age - lifetime <= max_stale_n:
                    verdict = FRESH
                else:
                    verdict = STALE
        else:
            verdict = STALE

    return Result(verdict=verdict, current_age=current_age, freshness_lifetime=lifetime)
